Method.Source:
AVAInventoryCockpit populateRecords()
{
    AVAInventoryCockpit tmpTable;
    InventItemLocation  inventItemLocation;
    InventTable         inventTable;
    InventDim           inventDim;
    InventLocation      inventLocation;
    InventLocationId    locId;
    Counter             counted, notCounted;
    KCS_KAOItemStateTable   itemState;
    InventItemGroup     itemGroup;

    while select inventItemLocation 
        join InventDim order by InventLocationId
        join inventLocation where inventDim.inventDimId == inventItemLocation.inventDimId
                               && inventLocation.InventLocationId == inventDim.InventLocationId
                               && inventLocation.AVACountCycleActive
    {
        inventTable = inventItemLocation.inventTable();
        itemState = KCS_KAOItemStateTable::find(inventTable.KCS_KAOItemState);
        itemGroup = inventTable.itemGroup();

        if (itemState.AVACountCycleActive && itemGroup.AVACountCycleActive)
        {
            if (locId != inventDim.InventLocationId)
            {
                tmpTable.clear();
                tmpTable.InventSiteId = InventLocation::find(locId).InventSiteId;
                tmpTable.InventLocationId = locId;
                tmpTable.Counted = counted;
                tmpTable.NotCounted = notCounted;
                tmpTable.InventorySum = Counted + notCounted;
                if ((counted + notCounted) > 0)
                {
                    tmpTable.Progress = counted / (counted + notCounted);
                }
                tmpTable.insert();

                locId = inventDim.InventLocationId;
                counted = 0;
                notCounted = 0;
            }
            if (inventItemLocation.AVAInvCountLast && DateTimeUtil::getStartOfYearDate(new Session().preferredLocale(), DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())) <= inventItemLocation.AVAInvCountLast)
            {
                counted++;
            }
            if (DateTimeUtil::getStartOfYearDate(new Session().preferredLocale(), DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())) > inventItemLocation.AVAInvCountLast && inventItemLocation.AVAInvCountNeeded)
            {
                notCounted++;
            }
        }
    }
    if (counted || notCounted)
    {
        tmpTable.clear();
        tmpTable.InventSiteId = InventLocation::find(locId).InventSiteId;
        tmpTable.InventLocationId = locId;
        tmpTable.Counted = counted;
        tmpTable.NotCounted = notCounted;
        tmpTable.InventorySum = Counted + notCounted;
        if ((counted + notCounted) > 0)
        {
            tmpTable.Progress = counted / (counted + notCounted);
        }
        tmpTable.insert();
    }


    return tmpTable;
}
